function renderVehicleInfo(){const brand=$('car-brand').value,key=brand+':'+$('jetour-model').value,info=vehicleSpecs[key];$('vehicle-info').hidden=!info;if(info){const items=info.items.concat(info.variantItems?.[$('powertrain').value]||[]);$('vehicle-info').innerHTML='<h3>'+info.title+'</h3><ul>'+items.map(x=>'<li>'+x+'</li>').join('')+(brand==='chery'?'<li>Межсервисный интервал CHERY: не более 10 000 км или 365 дней</li>':'')+'</ul><small>Источник: ' + info.source + '.</small>'}}
